// === Threads: Ответ для ИИ-агента по результатам поиска ===
// Ожидает вход от предыдущей ноды с { profile, total, top3 }.
// Пытается вытащить Query из текущего item или из ноды
// "When Executed by Another Workflow" (если имя ноды другое — поправь ниже).

// 1) Вход
const input = $input.all()[0]?.json || {};
const top3 = Array.isArray(input.top3) ? input.top3 : [];
const total = Number(input.total) || 0;

// 2) Пытаемся определить ключевое слово запроса
let query =
  input.query ||
  input.Query ||
  ($items('When Executed by Another Workflow', 0, 0)?.json?.Query) ||
  null;

// 3) Сколько строк реально вставили в таблицу (если нода называется "Insert row")
let insertedRows = null;
try {
  const ins = $items('Insert row');
  if (Array.isArray(ins)) insertedRows = ins.length;
} catch (e) {
  // ок, просто оставим null
}

// 4) Ссылки и компактные карточки топ-3
const links = top3.map(x => x.url).filter(Boolean);
const items = top3.map(x => ({
  rank: x.rank,
  url: x.url || null,
  like_count: x.like_count ?? null,
  comment_count: x.comment_count ?? null,
  createdAt: x.createdAt ?? null,
  caption_short: x.caption_short ?? null
}));

// 5) Сообщение
const prettyQuery = query ? `«${query}»` : '';
const wrote = insertedRows != null ? insertedRows : total;
const message = [
  `По запросу ${prettyQuery || 'без ключевого слова'} нашёл ${total} постов в Threads`,
  wrote != null ? `и записал в таблицу ${wrote}.` : '.',
  ' Три самых популярных — ниже по ссылкам.'
].join(' ');

// 6) Ответ для ИИ-агента
const result = {
  status: 'ok',
  message,
  query: query || null,
  total_found: total,
  inserted_rows: wrote,
  top_threads: {
    description: '3 популярных поста по запросу',
    links,
    items
  },
  generated_at: new Date().toISOString()
};

return [{ json: result }];

// === Threads: топ-3 популярных поста (Run Once for All Items) ===

// 1) Собираем строки
const rows = items.map(i => i.json);

// 2) Утилиты
const toNum = v => Number.isFinite(Number(v)) ? Number(v) : 0;

const toTime = (v) => {
  if (v == null) return 0;
  const n = Number(v);
  if (Number.isFinite(n)) {
    // unix seconds -> ms
    return n < 1e12 ? n * 1000 : n;
  }
  const t = Date.parse(String(v));
  return Number.isFinite(t) ? t : 0;
};

const cut = (s, words = 12) => String(s || '')
  .replace(/\s+/g, ' ')
  .trim()
  .split(' ')
  .slice(0, words)
  .join(' ');

const normUsername = (u) => (u ? String(u).replace(/^@/, '') : null);

function pickCaption(r) {
  return r?.caption?.text ?? r?.text ?? '';
}

function pickUsername(r) {
  return (
    r?.user?.username ??
    r?.owner?.username ??
    r?.username ??
    r?.profile?.username ??
    null
  );
}

function pickPostId(r) {
  return r?.pk ?? r?.post_id ?? r?.id ?? null;
}

function buildUrl(r) {
  if (r.URL) return r.URL;
  if (r.url) return r.url;
  const u = normUsername(pickUsername(r));
  const pid = pickPostId(r);
  return (u && pid) ? `https://www.threads.net/@${u}/post/${pid}` : null;
}

// 3) Нормализация
let normalized = rows.map(r => {
  const like = toNum(r.like_count ?? r.likes);
  const comm = toNum(r.comment_count ?? r.comments);
  const ts   = toTime(r.taken_at ?? r.createdAt ?? r.created_at ?? r.date);

  const score = like + 2 * comm; // без просмотров усиливаем вес комментариев

  const obj = {
    url: buildUrl(r),
    createdAt: ts ? new Date(ts).toISOString() : undefined,
    like_count: like,
    comment_count: comm || undefined,
    score,
    caption: pickCaption(r),
    caption_short: cut(pickCaption(r), 12),
  };

  // вычистим пустоты
  Object.keys(obj).forEach(k => (obj[k] == null || obj[k] === '') && delete obj[k]);
  return obj;
});

// 4) Фильтр и сортировка
normalized = normalized
  .filter(x => x.url) // нужен валидный URL
  .sort((a, b) =>
    (b.score - a.score) ||
    (b.like_count - a.like_count) ||
    ((b.comment_count || 0) - (a.comment_count || 0)) ||
    (toTime(b.createdAt) - toTime(a.createdAt))
  );

// 5) Топ-3 + ранги
const top3 = normalized.slice(0, 3).map((x, i) => ({ rank: i + 1, ...x }));

// 6) Профиль (базово — из первых строк, если есть)
function inferProfile(rows) {
  const r0 = rows[0] || {};
  const u = r0.user || r0.owner || {};
  const username = pickUsername(r0);
  const fullName = u.full_name ?? r0.full_name ?? r0.profile?.full_name ?? null;
  return {
    username: username ? `@${normUsername(username)}` : null,
    nickname: fullName || null,
  };
}

const profile = inferProfile(rows);

// 7) Результат
return [{ json: { profile, total: rows.length, top3 } }];

